import UIKit
let root = UIView(frame: CGRect(x: 0, y: 0, width: 320, height: 200))
let canvas = UIView(frame: CGRect(x: 20, y: 30, width: 120, height: 100))
let toolbar = UIView(frame: CGRect(x: 5, y: 5, width: 200, height: 150))
let sticker = UIView(frame: CGRect(x: 10, y: 20, width: 20, height: 10))
root.addSubview(canvas)
root.addSubview(toolbar)
canvas.addSubview(sticker)
let newFrame = sticker.convert(sticker.bounds, to: toolbar)
sticker.removeFromSuperview()
toolbar.addSubview(sticker)
sticker.frame = newFrame
let visualRect = sticker.convert(sticker.bounds, to: root)
assert(visualRect == CGRect(x: 30, y: 50, width: 20, height: 10))

Меняется локальная система, а не визуальное место. convert выполнен до разрыва старого дерева.
